// Форма Report -> кнопка переходу на рендер звіту (/<workspace>/report/<report_name>)
function on_load(frm) {
  if (frm.is_new) return;
  var reportName = frm.get_value('report_name');
  if (!reportName) return;
  frm.add_custom_button('Переглянути звіт', function () {
    grunt.set_route('report', reportName);
  }, null, { icon: 'file-bar-chart-2', variant: 'outline' });
}
